		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// Optimizations:
//  - Spatial blocking (tiling) in both i and j using noarr::into_blocks,
//    while preserving the original lexicographic (i, j) Gauss–Seidel order.
//    This improves cache locality without changing the mathematical update order.
//  - The interior region (i,j in [1,n-2]) is still expressed with noarr::slice,
//    but we additionally perform tiling *inside* that interior.
//  - A reciprocal of 9 is precomputed once to avoid repeated division in the
//    inner loop (the compiler is likely to do this anyway, but we make it
//    explicit and documented).
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// If the domain is too small to have a non-empty interior, nothing to do.
	if (n_i <= 2 || n_j <= 2)
		return;

	const std::size_t interior_i = n_i - 2; // number of interior rows
	const std::size_t interior_j = n_j - 2; // number of interior cols

	// ---------------------------------------------------------------------
	// Choose tile sizes for i and j.
	//
	// We want:
	//   - reasonably small tiles for cache locality, e.g. up to 32x32
	//   - tile sizes that divide the interior extents so that we can use
	//     plain noarr::into_blocks (which assumes divisibility)
	//   - gracefully fall back to smaller tiles (down to 1) if necessary
	//     to preserve correctness for arbitrary N.
	// ---------------------------------------------------------------------
	constexpr std::size_t tile_i_pref = 32;
	constexpr std::size_t tile_j_pref = 32;

	std::size_t tile_i = interior_i < tile_i_pref ? interior_i : tile_i_pref;
	while (tile_i > 1 && (interior_i % tile_i) != 0)
		--tile_i;

	std::size_t tile_j = interior_j < tile_j_pref ? interior_j : tile_j_pref;
	while (tile_j > 1 && (interior_j % tile_j) != 0)
		--tile_j;

	// Build a proto-structure describing:
	//   - restriction to the interior region [1, n_i-2] x [1, n_j-2]
	//   - 2D blocking in i ('I','i') and j ('J','j')
	//
	// Important:
	//   * We apply slice<'i'> and slice<'j'> *before* into_blocks so that the
	//     tiling is performed only on the interior region.
	//   * We do NOT hoist the block indices; the resulting traversal order is:
	//         I (outer), i (inner-within-tile), J, j
	//     which, when mapped back to the original (i,j), is exactly the same
	//     lexicographic order as the original (i outer, j inner) loop nest.
	//     This preserves Gauss–Seidel semantics while still improving locality
	//     (we operate on small tiles in cache, but in the same global order).
	auto interior_blocked =
		slice<'i'>(std::size_t(1), interior_i) ^
		slice<'j'>(std::size_t(1), interior_j) ^
		into_blocks<'i', 'I', 'i'>(tile_i) ^
		into_blocks<'j', 'J', 'j'>(tile_j);

	// Precompute the reciprocal of 9: numerically equivalent to dividing by 9,
	// but expressed as a multiplication in the inner loop.
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse only the interior points: i, j in [1, n-2],
		// blocked in both dimensions as described above.
		//
		// `slice` and `into_blocks` are applied via `order`, so the state seen
		// in the lambda still uses the original indices (1 .. n-2), suitable
		// for neighbor().
		noarr::traverser(A)
			.order(interior_blocked)
			.for_each([&](auto state) {
				auto s = state;

				// Build states for all 8 neighbors and the center
				auto s_im1_jm1 = neighbor<'i', 'j'>(s, -1, -1);
				auto s_im1_j   = neighbor<'i'>(s, -1);
				auto s_im1_jp1 = neighbor<'i', 'j'>(s, -1, +1);

				auto s_i_jm1   = neighbor<'j'>(s, -1);
				auto s_i_j     = s;
				auto s_i_jp1   = neighbor<'j'>(s, +1);

				auto s_ip1_jm1 = neighbor<'i', 'j'>(s, +1, -1);
				auto s_ip1_j   = neighbor<'i'>(s, +1);
				auto s_ip1_jp1 = neighbor<'i', 'j'>(s, +1, +1);

				num_t sum =
					A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
					A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1] +
					A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

				A[s_i_j] = sum * inv9;
			});
	}
	#pragma endscop
}

