//    proto-structure (`interior_tiling`) and then reused in every time step.
//    This avoids rebuilding the proto-structure inside the t-loop.
//
// 2. The interior is blocked in both spatial dimensions using
//    `into_blocks_static`:
//       - 'i' is split into ('Bi' – block-row index, 'i' – row-in-block)
//       - 'j' is split into ('Bj' – block-column index, 'j' – col-in-block)
//       - for each dimension there is also a small “body/border” selector.
//    The resulting traversal order is still lexicographic in the *original*
//    indices (i, j): rows are processed in increasing i, and within each row
//    columns are processed in increasing j. This preserves the exact
//    Gauss–Seidel dependence pattern while grouping iterations into
//    cache-friendly tiles internally to the traverser.
//
// 3. The denominator (9) is materialized once per kernel to avoid repeatedly
//    constructing the literal inside the innermost loop.
//
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	const std::size_t n_i = A | get_length<'i'>();
	const std::size_t n_j = A | get_length<'j'>();

	// Block sizes for tiling. These are small enough to fit typical L1/L2
	// caches while still large enough to amortize traverser overhead.
	constexpr std::size_t block_i = 32;
	constexpr std::size_t block_j = 32;

	// Describe the interior region and its tiling once and reuse it for all
	// time steps.
	//
	// - slice<'i'>(1, n_i-2) / slice<'j'>(1, n_j-2) restrict the traversal
	//   to interior points (i, j in [1, n-2]).
	// - into_blocks_static<'i', 'b', 'I', 'i'>(block_i) tiles the (sliced)
	//   'i' dimension into:
	//       'b' : body/border selector (tuple-like, values 0 or 1),
	//       'I' : block index in 'i',
	//       'i' : index within a block.
	//   The mapping from these internal indices back to the original 'i'
	//   is monotone and covers each interior row exactly once.
	// - into_blocks_static<'j', 'c', 'J', 'j'>(block_j) analogously tiles
	//   the (sliced) 'j' dimension.
	//
	// When used via traverser(...).order(interior_tiling), the states passed
	// to the lambda still only contain the original 'i' and 'j' indices,
	// already restricted to [1, n-2]. The extra tiling dimensions are
	// internal to the traverser and do not appear in the state.
	//
	// Overall ordering of (i, j) visited by the traverser remains:
	//   for i = 1 .. n_i-2
	//     for j = 1 .. n_j-2
	// which preserves the Gauss–Seidel update semantics exactly.
	auto interior_tiling =
		slice<'i'>(1, n_i - 2) ^
		slice<'j'>(1, n_j - 2) ^
		into_blocks_static<'i', 'b', 'I', 'i'>(block_i) ^
		into_blocks_static<'j', 'c', 'J', 'j'>(block_j);

