	for (int t = 0; t <= tsteps - 1; t++) {
		traverser(A)
			.order(interior_tiling)
			.for_each([&](auto state) {
				// `state` refers to a single interior grid point (i, j).
				// Thanks to `.order(slice(...))`, its indices are the original
				// ones in [1, n-2], so using neighbor() remains correct.

				auto s = state;

